    if len(nums) <= 1:
        return list(nums)
    a = list(nums)  # copy
    # Find first index i from right where a[i] < a[i+1]
    i = len(a) - 2
    while i >= 0 and a[i] >= a[i+1]:
        i -= 1
    if i == -1:
        # last permutation
        return sorted(a)
    # Find j from right where a[j] > a[i]
    j = len(a) - 1
    while a[j] <= a[i]:
        j -= 1
    # Swap
    a[i], a[j] = a[j], a[i]
    # Reverse suffix i+1 onward
    a[i+1:] = reversed(a[i+1:])
