def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each token is an integer or one of '+', '-', '*', '/'.
    Returns integer result with division truncated toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division truncates toward zero
                # Using int() on true division achieves truncation toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

