def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    meetings: iterable of [start, end] (or tuple). A meeting may start exactly when another ends.
    Intervals with start > end are ignored.
    """
    # Filter and normalize intervals
    intervals = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            # not a proper interval, skip
            continue
        if start <= end:
            intervals.append((start, end))
    if not intervals:
        return 0
    # Greedy by earliest finish time
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for start, end in intervals:
        if start >= current_end:
            count += 1
            current_end = end
    return count

