def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is a two‑element sequence [start, end] (or tuple). A meeting may start exactly when another ends.
    Intervals with start > end are treated as having the endpoints swapped.
    Non‑iterable or malformed entries are ignored.
    """
    # Gather valid intervals, normalise order
    intervals = []
    for m in meetings:
        try:
            s, e = m[0], m[1]
        except Exception:
            continue
        # Convert to numbers if possible
        try:
            s = int(s)
            e = int(e)
        except Exception:
            continue
        if s > e:
            s, e = e, s
        intervals.append((s, e))
    if not intervals:
        return 0
    # Greedy by earliest finish time
    intervals.sort(key=lambda x: (x[1], x[0]))
    cnt = 0
    cur_end = -float('inf')
    for s, e in intervals:
