def solve(tokens):
    """Evaluate Reverse Polish Notation with integer operations.
    Division truncates toward zero without using floating point.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Truncate toward zero using integer arithmetic
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                # Python's // floors toward -inf, adjust for truncation
                quotient = abs(a) // abs(b)
                res = quotient if (a * b) >= 0 else -quotient
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[-1] if stack else 0

