    """
    last = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        cur = i - start + 1
        if cur > max_len:
            max_len = cur
    return max_len

