def solve(nums):
    """Return the next lexicographic permutation of the list nums.
    If nums is the highest permutation, return the sorted list.
    Works for empty list as well.
    """
    n = len(nums)
    if n < 2:
        return list(nums)
    arr = list(nums)
    # Find first decreasing element from the right
    i = n - 2
    while i >= 0 and arr[i] >= arr[i + 1]:
        i -= 1
    if i == -1:
        return sorted(arr)
    # Find rightmost element greater than arr[i]
    j = n - 1
    while arr[j] <= arr[i]:
        j -= 1
    arr[i], arr[j] = arr[j], arr[i]
    # Reverse suffix
    arr[i + 1:] = reversed(arr[i + 1:])
    return arr

def solve(intervals):
    """Merge overlapping or touching intervals.
    Accepts an iterable of interval-like objects (list/tuple) with two elements.
    If an interval has start > end, the endpoints are swapped.
    Returns a list of merged intervals as lists, sorted by start.
    """
    # Normalize intervals
    norm = []
    for iv in intervals:
        try:
            s, e = iv[0], iv[1]
        except Exception:
            continue  # skip malformed
        # Ensure comparable numbers; attempt to convert to int if possible
        try:
            s = int(s)
            e = int(e)
        except Exception:
            try:
                s = float(s)
                e = float(e)
            except Exception:
                continue
        if s > e:
            s, e = e, s
        norm.append([s, e])
    if not norm:
        return []
    # Sort by start then end
    norm.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end = norm[0]
    for s, e in norm[1:]:
        if s <= cur_end:  # overlap or touch
            cur_end = max(cur_end, e)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged

