def solve(grid):
    """Count number of islands (connected components of 1s) in a grid.
    grid: list of lists of ints (0 or 1). Connectivity 4-directional.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = max(len(row) for row in grid) if rows else 0
    visited = [[False]*len(row) for row in grid]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if i<0 or i>=rows or j<0 or j>=len(grid[i]):
                continue
            if visited[i][j] or grid[i][j]!=1:
                continue
            visited[i][j]=True
            # four neighbors
            stack.append((i-1,j))
            stack.append((i+1,j))
            stack.append((i,j-1))
            stack.append((i,j+1))
    count=0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count+=1
    return count

