def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited
    coins of the given denominations *coins*. If it is impossible, return -1.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Remove non-positive coin values and duplicates
    coins = [c for c in set(coins) if c > 0]
    if not coins:
        return -1
    # Initialize DP array where dp[i] is min coins for amount i
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

