def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited
    supply of the given *coins*. If impossible, return -1.
    Uses classic DP with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    # DP array where dp[i] = min coins to make amount i
    INF = amount + 1  # larger than any possible solution
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If we can use coin c, see if using it leads to fewer coins
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

