def solve(nums):
    # Return the next lexicographic permutation of the list.
    # If the list is the last permutation, return the sorted list.
    if len(nums) <= 1:
        return list(nums)
    a = list(nums)
    # Find the first index i from the right where a[i] < a[i+1]
    i = len(a) - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i == -1:
        # Already the highest permutation
        return sorted(a)
    # Find the smallest element greater than a[i] to the right of i
    j = len(a) - 1
    while a[j] <= a[i]:
        j -= 1
    # Swap them
    a[i], a[j] = a[j], a[i]
    # Reverse the suffix after i
    a[i + 1:] = reversed(a[i + 1:])
    return a

def solve(n: int, b: int) -> str:
    """Convert integer *n* to a string representation in base *b* (2 <= b <= 36).
    Uses digits 0-9 and lowercase a-z. Negative numbers get a leading '-'.
    """
    if b < 2 or b > 36:
        raise ValueError('Base out of supported range 2-36')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    sign = '-' if n < 0 else ''
    n_abs = -n if n < 0 else n
    res = []
    while n_abs:
        n_abs, rem = divmod(n_abs, b)
        res.append(digits[rem])
    return sign + ''.join(reversed(res))

