def solve(intervals):
    """Merge overlapping or touching intervals.
    Accepts an iterable of interval-like objects (list/tuple) with two elements.
    If an interval has start > end, the endpoints are swapped.
    Returns a list of merged intervals (as lists) sorted by start.
    """
    # Normalize intervals: collect valid ones
    norm = []
    for iv in intervals:
        try:
            s, e = iv[0], iv[1]
        except Exception:
            continue
        # Ensure numbers (int or float). Attempt int conversion first.
        try:
            s = int(s)
            e = int(e)
        except Exception:
            try:
                s = float(s)
                e = float(e)
            except Exception:
                continue
        if s > e:
            s, e = e, s
        norm.append([s, e])
    if not norm:
        return []
    # Sort by start then end
    norm.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end = norm[0]
    for s, e in norm[1:]:
        if s <= cur_end:  # overlap or touch
            cur_end = max(cur_end, e)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged

