def solve(coins, amount):
    """Return the minimum number of coins needed to make up the given amount.
    If it's not possible, return -1.
    """
    # Edge case: amount 0 requires 0 coins
    if amount == 0:
        return 0
    # Initialize DP array with a value larger than any possible answer
    INF = amount + 1  # maximum coins needed can't exceed amount (using coin of value 1 if exists)
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If using coin c leads to a better solution, update
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

